package com.example.starter.cosmetic.testsupport;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

import java.time.Clock;
import java.time.Instant;

/**
 * 测试时钟配置：以可变时钟覆盖生产系统时钟。
 */
@TestConfiguration
public class TestClockConfiguration {

    /** 测试固定初始时刻(UTC)。 */
    public static final Instant INITIAL_NOW = Instant.parse("2026-06-30T08:00:00Z");

    /** 可控可变时钟。 */
    @Bean
    @Primary
    public MutableClock mutableClock() {
        return new MutableClock(INITIAL_NOW);
    }

    /** 以同一可变实例作为 Clock 类型主 Bean。 */
    @Bean
    @Primary
    public Clock clock(MutableClock mutableClock) {
        return mutableClock;
    }
}

